DO $rebase_companion$ BEGIN IF EXISTS (SELECT 1 FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = 'wiki' AND p.policyname = 'wiki_default_admin_write_delete_ar_896b743c' AND NOT (p.cmd = 'DELETE' AND p.permissive = 'PERMISSIVE' AND p.roles = ARRAY['rebase_admin_request']::name[] AND COALESCE(p.qual, 'true') = 'true' AND COALESCE(p.with_check, 'true') = 'true')) THEN EXECUTE 'DROP POLICY "wiki_default_admin_write_delete_ar_896b743c" ON "public"."wiki"'; END IF; END $rebase_companion$;
DROP POLICY IF EXISTS "wiki_default_admin_write_delete" ON "public"."wiki";
CREATE POLICY "wiki_default_admin_write_delete" ON "public"."wiki" AS PERMISSIVE FOR DELETE TO "rebase_admin" USING ((SELECT (rebase.uid() IS NULL) OR (string_to_array(rebase.roles(), ',') && ARRAY['admin'])));

